int16_t barrett_reduce(int16_t a) {
  // The reference computes a modulo 3329, centered in [-1664, 1664].
  // Its reciprocal approximation selects the nearest multiple for every int16_t.
  // Correct the signed remainder into that interval, including at both endpoints.
  int32_t r = (int32_t)a % 3329;
  if (r > 1664)
    r -= 3329;
  if (r < -1664)
    r += 3329;
  return (int16_t)r;
}

int16_t barrett_reduce(int16_t a) {
  // Add ten moduli and the centering offset before taking a remainder.
  // The dividend ranges from 2186 to 67721, so its remainder is nonnegative.
  // Subtracting 1664 yields the reference's centered residue for every input.
  int32_t x = (int32_t)a + 34954;
  return (int16_t)(x % 3329 - 1664);
}

int16_t barrett_reduce(int16_t a) {
  // Round the quotient to the nearest integer using a sign-dependent offset.
  // Division truncates toward zero; odd modulus 3329 prevents halfway ties.
  // All intermediates fit int32_t, including those for both int16_t endpoints.
  int32_t x = a;
  int32_t q = (x + (x >= 0 ? 1664 : -1664)) / 3329;
  return (int16_t)(x - q * 3329);
}

int16_t barrett_reduce(int16_t a) {
  // Reduce the magnitude to a centered residue, then restore the input's sign.
  // Centered reduction is odd because the odd modulus allows no halfway ties.
  // Widening before negation safely handles -32768 and every other input.
  int32_t x = a;
  int32_t magnitude = x < 0 ? -x : x;
  int32_t r = (magnitude + 1664) % 3329 - 1664;
  return (int16_t)(x < 0 ? -r : r);
}

int16_t barrett_reduce(int16_t a) {
  // Use the reference's exact reciprocal, 20159, and rounding numerator.
  // Explicit floor division reproduces its arithmetic right shift.
  // Wide arithmetic avoids overflow and narrowing of the intermediate product.
  // The final centered residue fits int16_t even at the input endpoints.
  int64_t n = (int64_t)20159 * a + 33554432;
  int32_t q = n >= 0
      ? (int32_t)(n / 67108864)
      : (int32_t)(-((-n + 67108863) / 67108864));
  return (int16_t)((int32_t)a - q * 3329);
}

int16_t barrett_reduce(int16_t a) {
  // Bias the reference numerator by ten times its power-of-two divisor.
  // This makes it positive for all int16_t inputs, so the shift is unambiguous.
  // Subtract ten from the quotient to undo the bias exactly.
  // Wide intermediates preserve the centered result at both input endpoints.
  int64_t n = (int64_t)20159 * a + 33554432
            + (int64_t)10 * 67108864;
  int32_t q = (int32_t)(n >> 26) - 10;
  return (int16_t)((int32_t)a - q * 3329);
}

int16_t barrett_reduce(int16_t a) {
  // Repeatedly add or subtract the modulus until the residue is centered.
  // Each step preserves congruence, and the centered representative is unique.
  // At most ten steps are needed, including for -32768 and 32767.
  int32_t r = a;
  while (r > 1664)
    r -= 3329;
  while (r < -1664)
    r += 3329;
  return (int16_t)r;
}

int16_t barrett_reduce(int16_t a) {
  // Shift into [2186, 67721], then compute the remainder by binary subtraction.
  // The dividend is below 32 moduli, so these five tests suffice for all inputs.
  // Removing the centering offset gives the reference's unique centered residue.
  int32_t r = (int32_t)a + 34954;
  if (r >= 53264)
    r -= 53264;
  if (r >= 26632)
    r -= 26632;
  if (r >= 13316)
    r -= 13316;
  if (r >= 6658)
    r -= 6658;
  if (r >= 3329)
    r -= 3329;
  return (int16_t)(r - 1664);
}

int16_t barrett_reduce(int16_t a) {
  // Recover the truncating-division remainder by multiplying the quotient.
  // Boolean corrections move it into the reference's centered interval.
  // Each comparison contributes zero or one; all arithmetic fits int32_t.
  // Strict comparisons preserve the valid boundary residues -1664 and 1664.
  int32_t x = a;
  int32_t r = x - (x / 3329) * 3329;
  r -= 3329 * (r > 1664);
  r += 3329 * (r < -1664);
  return (int16_t)r;
}

int16_t barrett_reduce(int16_t a) {
  // Binary-search the greatest quotient whose centered interval starts at or below a.
  // Quotients from -10 through 10 cover the entire int16_t input range.
  // The interval boundaries are q*3329-1664 and q*3329+1664.
  // Thus the final subtraction matches the reference, including all boundaries.
  int32_t x = a;
  int32_t lo = -10;
  int32_t hi = 10;
  while (lo < hi) {
    int32_t mid = lo + (hi - lo + 1) / 2;
    if (x >= mid * 3329 - 1664)
      lo = mid;
    else
      hi = mid - 1;
  }
  return (int16_t)(x - lo * 3329);
}
